"""Per-language Tree-sitter node types and capture queries for ingestion.

``LANGUAGE_REGISTRY`` drives function/class extraction in
:mod:`application.ingestion.process_code` and query compilation in
:mod:`infrastructure.parser.tree_sitter_parser`.
"""

from __future__ import annotations
from dataclasses import dataclass
from typing import Mapping
from infrastructure.logging.logger import get_logger
logger = get_logger(__name__)

@dataclass(frozen=True)
class LanguageSpec:
    """AST node sets and Tree-sitter query strings for one language."""
    function_node_types: frozenset[str]
    wrapper_types: frozenset[str]
    queries: Mapping[str, str]
    class_node_types: frozenset[str] = frozenset()

def supports_semantic_chunking(spec: LanguageSpec) -> bool:
    """Return whether the language has function queries suitable for AST chunking."""
    return bool(spec.function_node_types) and bool(str(spec.queries.get('functions', '')).strip())

_EMPTY: LanguageSpec = LanguageSpec(function_node_types=frozenset(), wrapper_types=frozenset(), queries={'functions': '', 'class_methods': '', 'attributes': ''})
_TYPESCRIPT_LIKE: LanguageSpec = LanguageSpec(function_node_types=frozenset({'function_declaration', 'method_definition', 'function'}), wrapper_types=frozenset({'export_statement'}), queries={'functions': '\n(function_declaration) @fn_def\n(method_definition) @fn_def\n(function) @fn_def\n', 'class_methods': '\n(class_declaration\n  name: (_) @class_name\n  body: (class_body\n    (method_definition\n      name: (_) @method_name)))\n', 'attributes': '\n(class_declaration\n  body: (class_body\n    (public_field_definition\n      (property_identifier) @attr_name)))\n'}, class_node_types=frozenset({'class_declaration'}))

def get_language_spec(lang: str) -> LanguageSpec:
    """Look up the :class:`LanguageSpec` for a Tree-sitter language id."""
    key = lang.lower().strip()
    if key not in LANGUAGE_REGISTRY:
        supported = ', '.join(sorted(LANGUAGE_REGISTRY))
        logger.error('get_language_spec: unknown language=%r (supported: %s)', lang, supported)
        raise KeyError(f'Unknown language {lang!r}. Supported: {supported}')
    logger.debug('get_language_spec: resolved language=%s', key)
    return LANGUAGE_REGISTRY[key]
